package vn.contractgovernance.api.customer;
import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import vn.contractgovernance.api.shared.*;
/** Reads an actual already-applied independent ContactRequest outcome, never gives DO checker powers. */
@Service public class ContactCorrectionProof {
 private final EntityStore store;private final JsonSupport json;
 public ContactCorrectionProof(EntityStore store,JsonSupport json){this.store=store;this.json=json;}
 public JsonNode verified(EntityStore.Entity relationship,JsonNode correction){if(!relationship.body().path("confirmedContact").equals(correction))throw ApiException.of("READINESS_BLOCKED","Correction cần normal ContactRequest được CHECKER approve trước privacy decision.");var rows=store.jdbc().query("select contact::text,request_id,confirmed_by,confirmed_at from cg_customer_contact_history where relationship_id=? and contact_version=?",(rs,n)->{var p=json.object();p.set("contact",json.parse(rs.getString(1)));if(rs.getObject(2)==null)p.putNull("requestId");else p.put("requestId",rs.getObject(2,UUID.class).toString());if(rs.getObject(3)==null)p.putNull("confirmedBy");else p.put("confirmedBy",rs.getObject(3,UUID.class).toString());p.put("confirmedAt",JsonSupport.timestamp(rs.getTimestamp(4).toInstant()));return p;},relationship.id(),relationship.body().path("contactVersion").asInt());if(rows.size()!=1||!rows.getFirst().path("contact").equals(correction)||!rows.getFirst().hasNonNull("requestId"))throw ApiException.of("READINESS_BLOCKED","Thiếu actual confirmed-contact approval source.");var p=rows.getFirst();var request=store.require("ContactRequest",UUID.fromString(p.path("requestId").asString()));if(!request.body().path("decision").asString().equals("APPROVED")||!request.body().path("relationshipId").asString().equals(relationship.id().toString())||!request.body().path("requestedContact").equals(correction)||!request.body().path("decidedBy").equals(p.path("confirmedBy")))throw ApiException.of("STORAGE_INTEGRITY","Contact approval/history không khớp.");for(var contributor:request.body().path("contributorIds"))if(contributor.equals(p.path("confirmedBy")))throw ApiException.of("SOD_VIOLATION","Contact approval không độc lập.");var prior=store.jdbc().query("select contact::text from cg_customer_contact_history where relationship_id=? and contact_version=?",(rs,n)->json.parse(rs.getString(1)),relationship.id(),relationship.body().path("contactVersion").asInt()-1);if(prior.size()!=1||!prior.getFirst().path("purpose").equals(correction.path("purpose")))throw ApiException.validation("/manifest/records/correction/purpose","Privacy correction không được đổi contact purpose.");p.put("contactVersion",relationship.body().path("contactVersion").asInt());p.put("requestVersion",request.version());return p;}
}
